def modulo(a,maxi,n,m):
	prev = 0
	for i in range(n):

		if a[i] > prev:
			t = m - (a[i] - prev)
			if t > maxi:
				prev = a[i]
		else:
			t = prev - a[i]
			if t>maxi:
				return False
	return True

