from collections import Counter
t = int(input())
for test in range(t):
	# num each digit
	# divisible by 60 <=> divisible by 10, after that by 2, and by 3
	n = {int(k):v for k, v in Counter(input()).items()}
	answer = "cyan"
	if 0 in n:
		n[0] -= 1 
		if n[0] == 0:
			del n[0]
		if not all([k%2 for k in n]) and sum([k*n[k] for k in n])%3==0:
			answer = "red"
	print(answer)

